command:
set -eu
:

wan_if="$(ip route show default | awk '{print $$5; exit}')"
cat > /tmp/router-rules.nft <<EOF
flush ruleset
table inet filter {
  chain forward {
    type filter hook forward priority 0; policy drop;
    ct state established,related accept
    iifname "lo" accept
    ip saddr 10.77.10.0/24 oifname "$$wan_if" accept
    ip saddr 10.250.1.0/29 oifname "$$wan_if" accept
  }
}
EOF

if [ -n "$$wan_if" ]; then
cat >> /tmp/router-rules.nft <<EOF2
table ip nat {
  chain postrouting {
    type nat hook postrouting priority srcnat; policy accept;
    oifname "$$wan_if" masquerade
  }
}
EOF2
fi
nft -f /tmp/router-rules.nft || echo "WARN: nft ruleset load failed" >&2

    tail -f /dev/null

set -eu
ip route replace default via 10.250.1.2 || true

wan_if="$(ip route show default | awk '{print $$5; exit}')"
cat > /tmp/router-rules.nft <<EOF
flush ruleset
table inet filter {
  chain forward {
    type filter hook forward priority 0; policy drop;
    ct state established,related accept
    iifname "lo" accept
    counter drop
  }
}
EOF
nft -f /tmp/router-rules.nft || echo "WARN: nft ruleset load failed" >&2

    tail -f /dev/null
